	// Пример добавления тестового промокода


	// Пример промокода с предметами только из определенных коллекций
	
	addNewPromocode('NAMELESS', 0, () => {
		// Только предметы с редкостью 'nameless' из определенных коллекций
		const filteredItems = itemsDatabase.filter(item => !item.isRental 
			&& item.rarity === 'nameless' && // удалить эту строку если без выбранной редкости
			['nameless_collection', ''].includes(item.collection)) // если коллекция 1, то сначала название коллекции и потом пустые кавычки
			.map(item => item.id);
		
		const result = [];
		for (let i = 0; i < 15; i++) {
			if (filteredItems.length > 0) {
				result.push(filteredItems[Math.floor(Math.random() * filteredItems.length)]);
			}
		}
		return result;
	}, false, 1);
	
	addNewPromocode('ДанилКолбасенко', 67, () => { // 67 Gold + 9 items
		const allItems = itemsDatabase.filter(item => !item.isRental).map(item => item.id);
		const result = [];
		for (let i = 0; i < 9; i++) {
			result.push(allItems[Math.floor(Math.random() * allItems.length)]);
		}
		return result;
	}, false, 1);
	
